package me.growapet.gui;
import me.growapet.GrowAPet;import me.growapet.models.PlayerData;import org.bukkit.Bukkit;import org.bukkit.Material;import org.bukkit.configuration.ConfigurationSection;import org.bukkit.entity.EntityType;import org.bukkit.entity.Player;import org.bukkit.inventory.ItemStack;import java.sql.PreparedStatement;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
public final class EggShopMenu extends Menu{
 private static final Set<UUID>BUSY=ConcurrentHashMap.newKeySet();private final GrowAPet plugin;public EggShopMenu(GrowAPet plugin,Player viewer){super(viewer,me.growapet.utils.Messages.parse("<aqua><bold>ZONE EGG SHOP</bold></aqua>"),54);this.plugin=plugin;}
 public void build(){PlayerData data=plugin.getPlayerManager().get(viewer);if(data==null)return;ConfigurationSection root=plugin.getConfigManager().eggs().getConfigurationSection("eggs");if(root==null)return;for(int i=0;i<54;i++)setItem(i,new ItemBuilder(Material.GRAY_STAINED_GLASS_PANE).name(" ").build(),null);me.growapet.zones.Zone current=plugin.getZoneManager().getZoneAt(viewer.getLocation());String zone=current==null?"spawn":current.getId();String zoneName=current==null?"Spawn":current.getDisplayName();setItem(4,new ItemBuilder(Material.TURTLE_EGG).name(me.growapet.utils.Messages.parse("<aqua><bold>"+zoneName.toUpperCase(java.util.Locale.ROOT)+" EGG SHOP</bold></aqua>")).loreComponents(List.of(me.growapet.utils.Messages.parse("<gray>• Catalog → <white>"+zone+"</white></gray>"),me.growapet.utils.Messages.parse("<gray>• Prices and hatch times are zone-specific</gray>"))).build(),null);int[]slots={10,11,12,13,14,15,16,19,20,21,22,23,24,25,28,29,30,31,32,33,34,37,38,39,40,41,42,43};int index=0;for(Map<?,?>raw:root.getMapList(zone)){if(index>=slots.length)break;try{EntityType type=EntityType.valueOf(String.valueOf(raw.get("entity")));if(!type.isAlive()||!type.isSpawnable()||type==EntityType.PLAYER||type==EntityType.ARMOR_STAND)continue;int seconds=Math.max(1,Math.min(604800,number(raw,"incubate-seconds",60).intValue()));long coins=number(raw,"price-coins",0).longValue(),gems=number(raw,"price-gems",0).longValue();if(coins<0||gems<0)continue;ItemStack item=new ItemBuilder(Material.TURTLE_EGG).name(me.growapet.utils.Messages.parse("<green><bold>"+type.name().replace('_',' ')+" EGG</bold></green>")).loreComponents(List.of(me.growapet.utils.Messages.parse("<gray>• Zone → <white>"+zoneName+"</white></gray>"),me.growapet.utils.Messages.parse("<gray>• Incubation → <white>"+seconds+"s</white></gray>"),me.growapet.utils.Messages.parse("<gray>• Coins → <yellow>"+coins+"</yellow></gray>"),me.growapet.utils.Messages.parse("<gray>• Gems → <aqua>"+gems+"</aqua></gray>"),me.growapet.utils.Messages.parse(""),me.growapet.utils.Messages.parse("<green>Click → purchase</green>"))).build();setItem(slots[index++],item,event->buy(type,seconds,coins,gems));}catch(Exception error){plugin.getLogger().warning("Invalid egg shop entry in "+zone+": "+error.getMessage());}}setItem(49,new ItemBuilder(Material.ARROW).name(me.growapet.utils.Messages.parse("<red><bold>BACK</bold></red>")).loreComponents(List.of(me.growapet.utils.Messages.parse("<gray>• Click → return to the shop</gray>"))).build(),event->new ShopMenu(plugin,viewer).open());}
 private void buy(EntityType type,int seconds,long coins,long gems){UUID playerId=viewer.getUniqueId();PlayerData data=plugin.getPlayerManager().get(playerId);if(data==null||!data.tryLockEconomy()){viewer.sendMessage("§cYou cannot purchase that egg right now.");return;}if(data.getCoins()<coins||data.getGems()<gems||!BUSY.add(playerId)){data.unlockEconomy();viewer.sendMessage("§cYou cannot purchase that egg right now.");return;}data.removeCoins(coins);data.removeGems(gems);String transactionId=UUID.randomUUID().toString(),deliveryId=UUID.randomUUID().toString();plugin.getDatabase().transaction(connection->{try(PreparedStatement debit=connection.prepareStatement("UPDATE players SET coins=coins-?,gems=gems-? WHERE uuid=? AND coins>=? AND gems>=?")){debit.setLong(1,coins);debit.setLong(2,gems);debit.setString(3,playerId.toString());debit.setLong(4,coins);debit.setLong(5,gems);if(debit.executeUpdate()!=1)throw new IllegalStateException("Insufficient balance");}try(PreparedStatement transaction=connection.prepareStatement("INSERT INTO economy_transactions(id,player_uuid,kind,coins_delta,gems_delta,created_at)VALUES(?,?,?,-?,-?,?)")){transaction.setString(1,transactionId);transaction.setString(2,playerId.toString());transaction.setString(3,"EGG_SHOP:"+type.name());transaction.setLong(4,coins);transaction.setLong(5,gems);transaction.setLong(6,System.currentTimeMillis());transaction.executeUpdate();}try(PreparedStatement delivery=connection.prepareStatement("INSERT INTO item_deliveries(id,player_uuid,item_type,item_data,created_at)VALUES(?,?,'EGG',?,?)")){delivery.setString(1,deliveryId);delivery.setString(2,playerId.toString());delivery.setString(3,type.name()+":"+seconds);delivery.setLong(4,System.currentTimeMillis());delivery.executeUpdate();}return null;}).whenComplete((ignored,error)->Bukkit.getScheduler().runTask(plugin,()->{BUSY.remove(playerId);data.unlockEconomy();if(error!=null){data.addCoinsRaw(coins);data.addGemsRaw(gems);if(viewer.isOnline())viewer.sendMessage("§cPurchase failed safely.");return;}if(viewer.isOnline()){viewer.closeInventory();viewer.sendMessage("§aPurchased a §e"+type+" egg§a.");}plugin.getTradeManager().deliverPending(playerId);}));}
 private static Number number(Map<?,?>map,String key,long fallback){Object value=map.get(key);return value instanceof Number number?number:fallback;}
}
